CREATE TABLE project (id INT PRIMARY KEY, description TEXT NOT NULL, intro TEXT NOT NULL, current_season_id CHAR(36) NULL);
CREATE TABLE seasons (id CHAR(36) PRIMARY KEY, ordinal INT NOT NULL UNIQUE, data LONGTEXT NOT NULL CHECK (JSON_VALID(data)));
CREATE TABLE users (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('PARENT_ADMIN','FAMILY_VIEWER') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, csrf CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE records (id CHAR(36) PRIMARY KEY, kind ENUM('stages','skills','lessons','practices','journal','contributions','expenses') NOT NULL, season_id CHAR(36) NOT NULL, data LONGTEXT NOT NULL CHECK (JSON_VALID(data)), FOREIGN KEY (season_id) REFERENCES seasons(id), INDEX record_season (kind,season_id));
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id CHAR(36) NULL, action VARCHAR(80) NOT NULL, target_id VARCHAR(80) NOT NULL, before_data LONGTEXT NULL, after_data LONGTEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE skill_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, skill_id CHAR(36) NOT NULL, actor_id CHAR(36) NOT NULL, old_status VARCHAR(20) NULL, new_status VARCHAR(20) NULL, feedback TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE media (id CHAR(36) PRIMARY KEY, journal_id CHAR(36) NOT NULL, storage_key CHAR(40) NOT NULL UNIQUE, mime VARCHAR(40) NOT NULL, size INT NOT NULL, FOREIGN KEY (journal_id) REFERENCES records(id) ON DELETE CASCADE);
CREATE TABLE invitations (id CHAR(36) PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, label VARCHAR(100) NOT NULL, expires_at DATETIME NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, used_by CHAR(36) NULL, FOREIGN KEY (used_by) REFERENCES users(id));
